#!/usr/bin/env python3
from pathlib import Path
import importlib.util,html,re,json
ROOT=Path(__file__).resolve().parents[1];TARGET=ROOT/'clase-bigquery'
spec=importlib.util.spec_from_file_location('clase_bigquery',TARGET/'guion.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
E=html.escape
rendered=[]
for i,s in enumerate(m.SLIDES,1):
 title='' if 'cover' in s['layout'].split() else f'<h1>{s["title"]}</h1>'
 cls=' '.join(x if x in ('cover','dark','statement') else 'kind-'+x for x in s['layout'].split())
 rendered.append(f'<section class="slide {cls}" data-id="BQ-{i:02}" data-title="{E(s["title"],quote=True)}" data-note="{E(s["note"],quote=True)}"><div class="eyebrow"><span>Clase independiente · {s["phase"]}</span><span>Chema Sarmiento</span></div>{title}<div class="content">{s["body"]}</div><div class="source"><span>{s["source"]}</span><span>{i:02} / {len(m.SLIDES)}</span></div></section>')
# Reutiliza el shell probado del curso, conservando la fuente de esta clase separada.
page=(ROOT/'especialidad-01/index.html').read_text()
page=re.sub(r'<title>.*?</title>','<title>BigQuery, arquitectura y Medallion · Clase ejecutiva</title>',page,count=1)
page=re.sub(r'<meta name="description"[^>]+>','<meta name="description" content="Clase autónoma de tres horas: BigQuery, arquitecturas, Medallion y laboratorio con muestra real de all_data.csv.">',page,count=1)
page=re.sub(r'(<main id="stage"[^>]*>).*?(</main>)',lambda x:x[1]+''.join(rendered)+x[2],page,count=1,flags=re.S)
page=page.replace('data-session="1"','data-session="bigquery"').replace('Ruta de la sesión 1','Ruta de la clase').replace('Laboratorio · sesión 1','Laboratorio · all_data.csv')
page=page.replace('</head>','<link rel="stylesheet" href="estilos.css"><script src="interacciones.js" defer></script></head>')
(TARGET/'index.html').write_text(page)
(TARGET/'notas-docente.md').write_text('# BigQuery, arquitectura y Medallion · 180 minutos\n\nFuente: guion.py. Los conteos son de la muestra; ejecución GoogleSQL en GCP pendiente.\n\n'+'\n\n'.join(f'## {i:02}. {s["title"]}\n\n{s["note"]}' for i,s in enumerate(m.SLIDES,1))+'\n')
(TARGET/'manifest.json').write_text(json.dumps({'title':'BigQuery, arquitectura y Medallion','minutes':180,'slides':len(m.SLIDES),'sample_rows':4500,'source':'guion.py','cloud_tested':False},ensure_ascii=False,indent=2)+'\n')
def link(f):return f'<a href="recursos/{f}" download>{f} ↓</a>'
def shell(title,body):return f'<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><link rel="stylesheet" href="../compartido/curso.css"><link rel="stylesheet" href="guia.css"></head><body><article class="guide"><a href="index.html">← Presentación</a><h1>{title}</h1>{body}</article></body></html>'
steps=[
('Bronze · ver lo que llegó',20,'10_bronze.sql',
'''Abre BigQuery Studio → SQL workspace → Nueva consulta. Carga all_data_muestra.csv en emergente_bronze.entrada con el esquema incluido: 15 columnas STRING, formato CSV y una fila de cabecera. Ejecuta estas consultas. Compara el valor original TLALPAN con municipio_limpio. Bronze conserva la entrada; todavía no corrige sus valores.''',
'4500 filas observadas. municipio conserva espacios finales y fechaRegistro mantiene fecha y hora.',
'Revisa delimitador coma, UTF-8, cabecera y comillas. No uses autodetección: las columnas crudas se guardan como STRING.'),
('Silver · limpiar, tipar y revisar qué se pierde',30,'20_silver.sql',
'''Abre otra consulta y ejecuta los siete bloques numerados en orden. 1: crea una tabla limpia (incluye direccion, no solo el nombre comercial). 2: guarda aparte los registros que no se pueden usar. 3: compara conteos. 4: busca filas que, ya limpias, quedaran idénticas en todos sus campos — TRIM y SAFE_CAST no detectan eso, solo agrupar sí. 5: desglosa POR QUÉ se rechazó cada fila, no solo cuántas. 6: confirma el periodo real de fechas. 7: compara precios por categoría, para no marcar como sospechoso un precio alto que es real en su categoría (televisores, lavadoras).''',
'4500 filas observadas y aceptadas; 0 para revisar; 0 filas idénticas repetidas (bloque 4); periodo observado 2011-01-10 a 2015-12-09 (bloque 6); precios hasta 13497 son electrodomésticos reales, no error (bloque 7).',
'Si SAFE_CAST devuelve NULL, busca la fila rechazada y lee el motivo en el bloque 5. Conserva la regla; revisa el valor original en Bronze. Si el bloque 4 no queda vacío, antes de seguir decide si esas filas son un error de carga o observaciones legítimas repetidas.'),
('Gold · preparar una comparación sin perder el conflicto de vista',30,'30_gold.sql',
'''Abre otra consulta y ejecuta los cuatro bloques. 1: Gold agrupa el precio por producto, marca, presentación, dirección, fecha y tienda — la dirección entra al grano para no fusionar dos tiendas distintas que comparten el mismo nombre comercial. 2: muestra el caso Sprite del 19 de marzo de 2014 en Tlalpan, con una columna estado_precio: dice "conflicto" solo si había más de un precio distinto en el mismo grupo; MIN() por sí solo no avisa, solo elige el menor en silencio. 3: escanea conflictos en TODA la muestra observada, no solo en el caso armado. 4: comprueba que el agregado no perdió ni duplicó filas de Silver.''',
'Dos establecimientos observados (direcciones distintas): 15.10 y 15.50 MXN, ambos marcados único. En toda la muestra (bloque 3): 0 de 4500 grupos en conflicto. Integridad (bloque 4): 2 observaciones en Gold, 2 filas en Silver — coinciden.',
'Si no aparecen dos filas, revisa fecha, producto, marca, presentación y municipio. Si el bloque 3 muestra grupos en conflicto, antes de usar el precio menor revisa si son en verdad la misma tienda. Si el bloque 4 no coincide, el GROUP BY perdió o duplicó algo — no lo ignores.'),
]
intro='''<p class="notice">Laboratorio ejecutivo · 80 minutos. Tres etapas y tres archivos SQL. En cada paso: abrir, copiar y ejecutar una consulta.</p><h2>Antes de empezar</h2><p>El docente prepara emergent_bronze, emergent_silver y emergent_gold en el proyecto de práctica. Así el grupo empieza mirando Bronze. Para cargar durante clase, sube all_data_muestra.csv como CSV en emergent_bronze.entrada, con las 15 columnas STRING de esquema-bronze.json. Se observaron 4500 filas en esta muestra de trabajo.</p><p>En Google Cloud: BigQuery → SQL workspace → Nueva consulta. Copia el bloque numerado y pulsa Ejecutar. El docente prepara el proyecto, permisos y facturación. No hace falta configurar la cuenta durante el laboratorio.</p><p>El archivo original pesa más de 20 GB. El docente lo prepara previamente en GCS; el grupo usa esta observación.</p><h2>Archivos del laboratorio</h2><ul><li>''' + link('10_bronze.sql') + ''' · ver Bronze como llegó.</li><li>''' + link('20_silver.sql') + ''' · limpiar, tipar y revisar qué se pierde.</li><li>''' + link('30_gold.sql') + ''' · preparar la comparación sin perder el conflicto de vista.</li><li>''' + link('all_data_muestra.csv') + ''' · datos observados para el laboratorio.</li><li>''' + link('perfil-muestra.json') + ''' · cómo se eligió.</li></ul>'''

files=sorted(p.name for p in (TARGET/'recursos').iterdir() if p.is_file())
body=intro
for n,(title,minutes,f,action,check,recover) in enumerate(steps,1):
 body+=f'<section id="paso-{n}"><h2>Paso {n} · {title} · {minutes} min</h2>'+''.join(f'<p>{E(t)}</p>' for t in action.split('\n'))+f'<p><strong>Comprueba:</strong> {E(check)}</p><p><strong>Si no coincide:</strong> {E(recover)}</p><p>{link(f)}</p><details><summary>Ver consultas</summary><pre><code>{E((TARGET/"recursos"/f).read_text())}</code></pre></details></section>'
body+='''<h2>Ruta docente para el archivo completo</h2><p>Conservar el original en un bucket autorizado, con nombre de objeto, tamaño, generación/checksum y manifiesto. Cargar desde GCS directamente a emergente_bronze.entrada con el mismo esquema de 15 columnas STRING — no transferir 20.7 GB a un disco local ni a Cloud Shell. Antes de correr 20_silver.sql y 30_gold.sql sobre el archivo completo, repetir el bloque 4 de Silver (filas idénticas repetidas) y revisar cuántos grupos de Gold quedan con estado_precio = conflicto: en la muestra observada ninguno lo tuvo, y eso no prueba que el archivo completo se comporte igual. Ejecutar una vez, guardar controles y usar tablas preparadas en clase. El diseño no presupone que lo observado en la muestra valide todas las filas del archivo.</p><p>Para optimizar: selecciona las columnas necesarias, filtra por fecha y revisa el estimado de bytes antes de ejecutar. LIMIT limita las filas de salida; no necesariamente los datos leídos. Con el archivo completo, el docente ensaya y comparte los resultados.</p><h2>Fuentes</h2><p>Consulta2026-11-09: <a href="https://docs.cloud.google.com/bigquery/docs/running-queries">ejecutar consultas</a>, <a href="https://docs.cloud.google.com/bigquery/docs/best-practices-costs">control de costos</a>, <a href="https://docs.cloud.google.com/bigquery/docs/partitioned-tables">particiones</a> y <a href="https://cloud.google.com/discover/what-is-a-data-lakehouse">lakehouse</a>.</p><p><a href="tarea.html">Tarea de actualización →</a></p>'''
(TARGET/'laboratorio.html').write_text(shell('Laboratorio · all_data.csv en BigQuery',body))
task='''<p>Objetivo: incorporar un corte adicional de QQP y demostrar qué cambió sin perder el histórico. La actualización es posterior a la clase. No publicar una recomendación actual a partir de fechas históricas.</p><ol><li>Localiza un archivo acotado en el <a href="https://datos.profeco.gob.mx/">catálogo oficial PROFECO</a>. Registra URL, periodo, fecha de descarga, licencia/condiciones, tamaño y checksum. Conserva el original. No se ha validado aquí el esquema de la entrega nueva.</li><li>Abre su cabecera y documenta el mapa a las 15 columnas del taller. Comprueba delimitador, codificación, tipos, unidades y formato de fecha. Ejemplos condicionales: fecha_registro→fechaRegistro; cadena_comercial→cadenaComercial. No inventes campos ausentes ni conviertas marca S/M en una identidad cierta. Si el contrato no encaja, explica qué adaptación requiere.</li><li>Carga la entrega adaptada en entrada con sobrescritura solo de esa tabla. Conserva all_data y todos los lotes Bronze. Ejecuta 01 con un nuevo lote_id y fuente_uri. La ruta es serial; no ejecutar dos ingestas concurrentes.</li><li>Perfila el nuevo lote modificando el filtro de 02. Guarda conteos, fechas y conversiones. Ejecuta 03 para reconstruir Silver y04 con el periodo que quieras comparar. Esta ruta releeBronze completo: medir su costo, no llamarla incremental.</li><li>Prueba idempotencia: el mismo ID de lote se rechaza; repetir las mismas filas en un lote de prueba distinto no debe aumentar las firmas únicas deSilver. Bronze sí registra las filas recibidas. Un precio corregido tiene firma distinta y debe permanecer trazable; si contradice otro del mismo grupo/día,Gold muestra conflicto.</li><li>Propón una optimización incremental: procesar lotes nuevos, deduplicar contra firmas existentes y recalcular únicamente particiones y agregados afectados. Incluye llegadas tardías, correcciones, cambios de esquema y conciliación. No necesitas implementar un MERGE genérico sin contrato.</li><li>Compara un producto realmente equivalente entre periodos, explicando cambios de población, marca, presentación ytienda. No etiquetes esa diferencia como inflación oficial ni ahorro realizable.</li></ol><h2>Entrega</h2><p>Manifiesto del lote y mapa de columnas; SQL ejecutado; conteosBronze/Silver/Gold antes/después; prueba de repetición; conflictos y tratamiento; jobs/bytes reales; recomendación ejecutiva de una página y arquitectura elegida.</p><h2>Criterios ·100 puntos</h2><ul><li>20: procedencia y contrato del lote.</li><li>30: calidad, reconciliación y repetición comprobada.</li><li>20:Gold y comparación con grano explícito.</li><li>20: medición de costo y propuesta de optimización.</li><li>10: decisión y límites comprensibles.</li></ul><p>Si falta acceso al motor, registra ejecución pendiente y presenta la revisión técnica; no sustituye evidencia de ejecución. Consulta <a href="laboratorio.html">la guía</a> y conserva los recursos según retención acordada.</p>'''
(TARGET/'tarea.html').write_text(shell('Tarea · incorporar una entrega nueva sin perder historia',task))
print(f'Clase BigQuery: {len(m.SLIDES)} slides,180 min; laboratorio80 min y tarea independiente.')
